// Package mp4 adapts github.com/abema/go-mp4 to the platform's restricted
// fragmented-MP4 fixture profile. It enforces strict structural validation
// (truncation, illegal lengths, out-of-range offsets, depth and allocation
// limits) and exposes a flat, auditable sample model.
package mp4

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"

	"github.com/abema/go-mp4"

	"mediapipe/internal/meta"
)

// Structural limits. Fixtures are generated by this project and stay far below
// these bounds; anything larger is rejected before allocation.
const (
	MaxFileBytes     = 8 << 20
	MaxBoxes         = 4096
	MaxDepth         = 8
	MaxTrackCount    = 8
	MaxSamplesPerSeg = 2048
	MaxSamplesTotal  = 16384
	MaxEmsgPerFile   = 64
	MaxSampleEntry   = 512
	MaxParams        = 16
)

var (
	ErrTruncatedBox      = errors.New("mp4: truncated box")
	ErrIllegalLength     = errors.New("mp4: illegal box length")
	ErrOffsetOutOfRange  = errors.New("mp4: offset out of range")
	ErrDepth             = errors.New("mp4: box nesting too deep")
	ErrLimit             = errors.New("mp4: structural limit exceeded")
	ErrTrackMismatch     = errors.New("mp4: track ownership mismatch")
	ErrUnsupportedLayout = errors.New("mp4: unsupported layout")
	ErrSampleFlags       = errors.New("mp4: invalid sample flags")
)

// NonSyncSampleFlag is the ISO sample_is_non_sync_sample bit.
const NonSyncSampleFlag uint32 = 0x00010000

// Colr is normalized color metadata from a colr box.
type Colr struct {
	Primaries uint16
	Transfer  uint16
	Matrix    uint16
	FullRange bool
}

// Equal reports exact equality; differences are never auto-corrected.
func (c Colr) Equal(o Colr) bool { return c == o }

// VideoLayout is the declaration carried by a visual sample entry.
type VideoLayout struct {
	Width, Height uint16
	Color         *Colr
}

// AudioLayout is the declaration carried by an audio sample entry.
type AudioLayout struct {
	ChannelCount uint16
	SampleSize   uint16
	SampleRate   uint32 // Hz, integer part
}

// ClockEntry is one stts run from the moov sample table.
type ClockEntry struct {
	Count uint32
	Delta uint32
}

// Track is the declaration part of a track found in moov.
type Track struct {
	ID                  uint32
	Handler             string
	Timescale           uint32
	Duration            uint64
	Language            string
	Video               *VideoLayout
	Audio               *AudioLayout
	Stts                []ClockEntry
	DeclaredSampleCount uint32
	SampleEntry         string
}

// Sample is one decoded sample described by a trun and backed by mdat bytes.
type Sample struct {
	TrackID  uint32
	Index    uint32 // 1-based within the track in this file
	DTS      uint64
	CTS      int64 // DTS + composition offset; may be earlier than DTS
	Duration uint32
	Size     uint32
	Flags    uint32
	Sync     bool
	Offset   uint64 // absolute file offset of the sample data
	Payload  []byte
	Digest   [32]byte
}

// SegmentTrack groups the samples of one track inside one moof.
type SegmentTrack struct {
	TrackID    uint32
	BaseDecode uint64
	Samples    []Sample
}

// Segment is one moof+mdat pair with its sequence number.
type Segment struct {
	Sequence uint32
	MoofOff  uint64
	MdatOff  uint64
	Tracks   []*SegmentTrack
	Emsg     []meta.Emsg
}

// File is a fully parsed fixture.
type File struct {
	Timescale uint32
	Duration  uint64
	Tracks    []*Track
	Segments  []*Segment
	Bytes     int
	Boxes     int
}

// TrackByID looks up a declared track.
func (f *File) TrackByID(id uint32) *Track {
	for _, t := range f.Tracks {
		if t.ID == id {
			return t
		}
	}
	return nil
}

type walker struct {
	data  []byte
	boxes int
}

func (w *walker) walk(start, end uint64, depth int, visit func(typ string, payload, full []byte, off uint64) error) error {
	if depth > MaxDepth {
		return fmt.Errorf("%w: depth %d", ErrDepth, depth)
	}
	pos := start
	for pos < end {
		w.boxes++
		if w.boxes > MaxBoxes {
			return fmt.Errorf("%w: box count", ErrLimit)
		}
		if end-pos < 8 {
			return fmt.Errorf("%w: %d trailing bytes at %d", ErrTruncatedBox, end-pos, pos)
		}
		size := uint64(binary.BigEndian.Uint32(w.data[pos : pos+4]))
		typ := string(w.data[pos+4 : pos+8])
		hdr := uint64(8)
		switch size {
		case 0:
			size = end - pos
		case 1:
			if end-pos < 16 {
				return fmt.Errorf("%w: large header at %d", ErrTruncatedBox, pos)
			}
			size = binary.BigEndian.Uint64(w.data[pos+8 : pos+16])
			hdr = 16
		}
		if size < hdr {
			return fmt.Errorf("%w: box %q size %d < header %d at %d", ErrIllegalLength, typ, size, hdr, pos)
		}
		if size > end-pos {
			return fmt.Errorf("%w: box %q size %d beyond parent end %d at %d", ErrTruncatedBox, typ, size, end, pos)
		}
		full := w.data[pos : pos+size]
		payload := full[hdr:]
		if visit != nil {
			if err := visit(typ, payload, full, pos); err != nil {
				return err
			}
		}
		if isContainer(typ) {
			childStart := pos + hdr
			if typ == "stsd" {
				if size < hdr+8 {
					return fmt.Errorf("%w: stsd short", ErrIllegalLength)
				}
				childStart += 8
			}
			if err := w.walk(childStart, pos+size, depth+1, visit); err != nil {
				return err
			}
		}
		pos += size
	}
	return nil
}

func isContainer(typ string) bool {
	switch typ {
	case "moov", "trak", "mdia", "minf", "stbl", "mvex", "moof", "traf",
		"dinf", "edts", "udta", "stsd":
		return true
	}
	return false
}

func unmarshalBox(payload []byte, dst mp4.IBox) error {
	if _, err := mp4.Unmarshal(bytes.NewReader(payload), uint64(len(payload)), dst, mp4.Context{}); err != nil {
		return fmt.Errorf("mp4: unmarshal %s: %w", dst.GetType(), err)
	}
	return nil
}

// ParseFile validates and decodes a complete fixture.
func ParseFile(data []byte) (*File, error) {
	if len(data) > MaxFileBytes {
		return nil, fmt.Errorf("%w: file %d bytes", ErrLimit, len(data))
	}
	f := &File{Bytes: len(data)}
	tracks := map[uint32]*Track{}
	var mdats [][2]uint64 // payload start, end
	var pendingEmsg []meta.Emsg
	var lastMoof *Segment
	segSeen := map[uint32]bool{}
	sampleTotal := 0

	w := &walker{data: data}
	err := w.walk(0, uint64(len(data)), 0, func(typ string, payload, full []byte, off uint64) error {
		switch typ {
		case "mvhd":
			var box mp4.Mvhd
			if err := unmarshalBox(payload, &box); err != nil {
				return err
			}
			if box.Timescale == 0 {
				return fmt.Errorf("%w: mvhd timescale 0", ErrIllegalLength)
			}
			if f.Timescale != 0 {
				return fmt.Errorf("%w: duplicate mvhd", ErrIllegalLength)
			}
			f.Timescale = box.Timescale
			f.Duration = box.GetDuration()
		case "trak":
			tr, err := parseTrak(full)
			if err != nil {
				return err
			}
			if _, dup := tracks[tr.ID]; dup {
				return fmt.Errorf("%w: duplicate track %d", ErrTrackMismatch, tr.ID)
			}
			if len(tracks) >= MaxTrackCount {
				return fmt.Errorf("%w: track count", ErrLimit)
			}
			if tr.Timescale == 0 {
				return fmt.Errorf("%w: track %d timescale 0", ErrIllegalLength, tr.ID)
			}
			tracks[tr.ID] = tr
			f.Tracks = append(f.Tracks, tr)
		case "mdat":
			mdats = append(mdats, [2]uint64{off + 8, off + uint64(len(full))})
			if lastMoof != nil && lastMoof.MdatOff == 0 {
				lastMoof.MdatOff = off
				lastMoof = nil
			}
		case "moof":
			seg, err := parseMoof(full, off)
			if err != nil {
				return err
			}
			if segSeen[seg.Sequence] {
				return fmt.Errorf("%w: duplicate fragment sequence %d", ErrIllegalLength, seg.Sequence)
			}
			segSeen[seg.Sequence] = true
			if len(seg.Emsg) == 0 {
				seg.Emsg = append(seg.Emsg, pendingEmsg...)
			}
			pendingEmsg = nil
			f.Segments = append(f.Segments, seg)
			lastMoof = seg
		case "emsg":
			if len(pendingEmsg) >= MaxEmsgPerFile {
				return fmt.Errorf("%w: emsg count", ErrLimit)
			}
			e, err := meta.ParseEmsgPayload(payload)
			if err != nil {
				return err
			}
			pendingEmsg = append(pendingEmsg, e)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if f.Timescale == 0 {
		return nil, fmt.Errorf("%w: moov without mvhd", ErrUnsupportedLayout)
	}
	if len(f.Tracks) == 0 {
		return nil, fmt.Errorf("%w: no tracks", ErrUnsupportedLayout)
	}
	if len(f.Segments) == 0 {
		return nil, fmt.Errorf("%w: no media segments", ErrUnsupportedLayout)
	}
	if len(pendingEmsg) > 0 {
		f.Segments[len(f.Segments)-1].Emsg = append(f.Segments[len(f.Segments)-1].Emsg, pendingEmsg...)
	}
	// Resolve sample payloads against mdat ranges.
	for _, seg := range f.Segments {
		for _, st := range seg.Tracks {
			if _, ok := tracks[st.TrackID]; !ok {
				return nil, fmt.Errorf("%w: sample track %d undeclared", ErrTrackMismatch, st.TrackID)
			}
			if len(st.Samples) > MaxSamplesPerSeg {
				return nil, fmt.Errorf("%w: %d samples in fragment", ErrLimit, len(st.Samples))
			}
			sampleTotal += len(st.Samples)
			if sampleTotal > MaxSamplesTotal {
				return nil, fmt.Errorf("%w: %d samples total", ErrLimit, sampleTotal)
			}
			for i := range st.Samples {
				s := &st.Samples[i]
				if s.Size > MaxSampleEntry {
					return nil, fmt.Errorf("%w: sample size %d", ErrLimit, s.Size)
				}
				end := s.Offset + uint64(s.Size)
				if end < s.Offset || end > uint64(len(data)) {
					return nil, fmt.Errorf("%w: sample end %d beyond file %d", ErrOffsetOutOfRange, end, len(data))
				}
				if !inMdat(mdats, s.Offset, end) {
					return nil, fmt.Errorf("%w: sample [%d,%d) outside mdat", ErrOffsetOutOfRange, s.Offset, end)
				}
				s.Payload = append([]byte(nil), data[s.Offset:end]...)
				s.Digest = sha256.Sum256(s.Payload)
			}
		}
	}
	f.Boxes = w.boxes
	return f, nil
}

func inMdat(mdats [][2]uint64, start, end uint64) bool {
	for _, m := range mdats {
		if start >= m[0] && end <= m[1] && end >= start {
			return true
		}
	}
	return false
}

func parseTrak(full []byte) (*Track, error) {
	tr := &Track{}
	w := &walker{data: full, boxes: 0}
	err := w.walk(0, uint64(len(full)), 0, func(typ string, payload, box []byte, off uint64) error {
		switch typ {
		case "tkhd":
			var box64 mp4.Tkhd
			if err := unmarshalBox(payload, &box64); err != nil {
				return err
			}
			tr.ID = box64.TrackID
		case "mdhd":
			var box64 mp4.Mdhd
			if err := unmarshalBox(payload, &box64); err != nil {
				return err
			}
			tr.Timescale = box64.Timescale
			tr.Duration = box64.GetDuration()
			tr.Language = string(box64.Language[:])
		case "hdlr":
			var box64 mp4.Hdlr
			if err := unmarshalBox(payload, &box64); err != nil {
				return err
			}
			tr.Handler = string(box64.HandlerType[:])
		case "stts":
			var box64 mp4.Stts
			if err := unmarshalBox(payload, &box64); err != nil {
				return err
			}
			if box64.EntryCount > MaxParams {
				return fmt.Errorf("%w: stts entries %d", ErrLimit, box64.EntryCount)
			}
			for _, e := range box64.Entries {
				tr.Stts = append(tr.Stts, ClockEntry{Count: e.SampleCount, Delta: e.SampleDelta})
			}
		case "stsz":
			var box64 mp4.Stsz
			if err := unmarshalBox(payload, &box64); err != nil {
				return err
			}
			if box64.SampleCount > MaxSamplesTotal {
				return fmt.Errorf("%w: stsz samples %d", ErrLimit, box64.SampleCount)
			}
			tr.DeclaredSampleCount = box64.SampleCount
		case "avc1", "encv":
			var se mp4.VisualSampleEntry
			se.SetType(mp4.StrToBoxType(typ))
			if _, err := mp4.Unmarshal(bytes.NewReader(payload), uint64(len(payload)), &se, mp4.Context{}); err != nil {
				return fmt.Errorf("mp4: visual sample entry: %w", err)
			}
			tr.Video = &VideoLayout{Width: se.Width, Height: se.Height}
			tr.SampleEntry = typ
			if err := parseVisualChildren(tr, payload); err != nil {
				return err
			}
		case "mp4a", "enca":
			var se mp4.AudioSampleEntry
			se.SetType(mp4.StrToBoxType(typ))
			if _, err := mp4.Unmarshal(bytes.NewReader(payload), uint64(len(payload)), &se, mp4.Context{}); err != nil {
				return fmt.Errorf("mp4: audio sample entry: %w", err)
			}
			tr.Audio = &AudioLayout{ChannelCount: se.ChannelCount, SampleSize: se.SampleSize, SampleRate: se.SampleRate >> 16}
			tr.SampleEntry = typ
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if tr.ID == 0 {
		return nil, fmt.Errorf("%w: trak without tkhd", ErrUnsupportedLayout)
	}
	if tr.Handler == "" {
		return nil, fmt.Errorf("%w: track %d without hdlr", ErrUnsupportedLayout, tr.ID)
	}
	return tr, nil
}

// parseVisualChildren walks the boxes that follow the 78-byte visual sample
// entry header. Only colr is retained; unknown children are rejected.
func parseVisualChildren(tr *Track, payload []byte) error {
	const visualHeader = 78
	if len(payload) < visualHeader {
		return fmt.Errorf("%w: visual entry short", ErrTruncatedBox)
	}
	rest := payload[visualHeader:]
	pos := 0
	for pos < len(rest) {
		if len(rest)-pos < 8 {
			return fmt.Errorf("%w: visual child header", ErrTruncatedBox)
		}
		size := int(binary.BigEndian.Uint32(rest[pos : pos+4]))
		typ := string(rest[pos+4 : pos+8])
		if size < 8 || size > len(rest)-pos {
			return fmt.Errorf("%w: visual child %q size %d", ErrIllegalLength, typ, size)
		}
		body := rest[pos+8 : pos+size]
		switch typ {
		case "avcC":
			var c mp4.AVCDecoderConfiguration
			c.SetType(mp4.BoxTypeAvcC())
			if _, err := mp4.Unmarshal(bytes.NewReader(body), uint64(len(body)), &c, mp4.Context{}); err != nil {
				return fmt.Errorf("mp4: avcC: %w", err)
			}
		case "colr":
			var c mp4.Colr
			if err := unmarshalBox(body, &c); err != nil {
				return err
			}
			if string(c.ColourType[:]) != "nclx" {
				return fmt.Errorf("%w: colr type %q", ErrUnsupportedLayout, string(c.ColourType[:]))
			}
			tr.Video.Color = &Colr{Primaries: c.ColourPrimaries, Transfer: c.TransferCharacteristics,
				Matrix: c.MatrixCoefficients, FullRange: c.FullRangeFlag}
		default:
			return fmt.Errorf("%w: visual child %q", ErrUnsupportedLayout, typ)
		}
		pos += size
	}
	return nil
}

func parseMoof(full []byte, moofOff uint64) (*Segment, error) {
	seg := &Segment{MoofOff: moofOff}
	var cur *SegmentTrack
	w := &walker{data: full, boxes: 0}
	err := w.walk(0, uint64(len(full)), 0, func(typ string, payload, box []byte, off uint64) error {
		switch typ {
		case "mfhd":
			var b mp4.Mfhd
			if err := unmarshalBox(payload, &b); err != nil {
				return err
			}
			seg.Sequence = b.SequenceNumber
		case "traf":
			cur = nil
		case "tfhd":
			var b mp4.Tfhd
			if err := unmarshalBox(payload, &b); err != nil {
				return err
			}
			if b.TrackID == 0 {
				return fmt.Errorf("%w: tfhd track 0", ErrIllegalLength)
			}
			if cur != nil && cur.TrackID != b.TrackID {
				return fmt.Errorf("%w: trun/tfhd track mismatch", ErrTrackMismatch)
			}
			if cur == nil {
				cur = &SegmentTrack{TrackID: b.TrackID}
				seg.Tracks = append(seg.Tracks, cur)
			}
		case "tfdt":
			if cur == nil {
				return fmt.Errorf("%w: tfdt before tfhd", ErrUnsupportedLayout)
			}
			var b mp4.Tfdt
			if err := unmarshalBox(payload, &b); err != nil {
				return err
			}
			cur.BaseDecode = b.GetBaseMediaDecodeTime()
		case "trun":
			if cur == nil {
				return fmt.Errorf("%w: trun before tfhd", ErrUnsupportedLayout)
			}
			var b mp4.Trun
			if err := unmarshalBox(payload, &b); err != nil {
				return err
			}
			if b.SampleCount > MaxSamplesPerSeg || int(b.SampleCount) != len(b.Entries) {
				return fmt.Errorf("%w: trun samples %d/%d", ErrIllegalLength, b.SampleCount, len(b.Entries))
			}
			if !b.CheckFlag(0x1) {
				return fmt.Errorf("%w: trun without data offset", ErrUnsupportedLayout)
			}
			dataStart := int64(moofOff) + int64(b.DataOffset)
			if dataStart < 0 {
				return fmt.Errorf("%w: negative data offset", ErrOffsetOutOfRange)
			}
			dts := cur.BaseDecode
			offset := uint64(dataStart)
			for _, e := range b.Entries {
				if e.SampleSize == 0 || e.SampleSize > MaxSampleEntry {
					return fmt.Errorf("%w: sample size %d", ErrIllegalLength, e.SampleSize)
				}
				flags := e.SampleFlags
				if !b.CheckFlag(0x4) || len(cur.Samples) > 0 {
					// first_sample_flags applies to entry 0 only when present
				}
				cts := int64(dts)
				if b.CheckFlag(0x800) {
					if b.GetVersion() == 0 {
						cts += int64(e.SampleCompositionTimeOffsetV0)
					} else {
						cts += int64(e.SampleCompositionTimeOffsetV1)
					}
				}
				if cts < 0 {
					return fmt.Errorf("%w: negative composition time", ErrOffsetOutOfRange)
				}
				cur.Samples = append(cur.Samples, Sample{
					TrackID:  cur.TrackID,
					Index:    uint32(len(cur.Samples) + 1),
					DTS:      dts,
					CTS:      cts,
					Duration: e.SampleDuration,
					Size:     e.SampleSize,
					Flags:    flags,
					Sync:     flags&NonSyncSampleFlag == 0,
					Offset:   offset,
				})
				dts += uint64(e.SampleDuration)
				offset += uint64(e.SampleSize)
			}
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if seg.Sequence == 0 {
		return nil, fmt.Errorf("%w: moof sequence 0", ErrIllegalLength)
	}
	for _, st := range seg.Tracks {
		if len(st.Samples) == 0 {
			return nil, fmt.Errorf("%w: track %d fragment has no samples", ErrUnsupportedLayout, st.TrackID)
		}
	}
	return seg, nil
}
